text:
{
  "questions": [
    {
      "n": 1,
      "start": "Quelle est l’appréciation de la Municipalité",
      "end": "sur l’importance du sauvetage"
    },
    {
      "n": 2,
      "start": "Comment la Municipalité soutient-elle ces activités, en particulier",
      "end": "sous les angles suivants"
    },
    {
      "n": 3,
      "start": "Comment d’autres collectivités (autres communes, canton)",
      "end": "soutiennent-elles ces activités ?"
    },
    {
      "n": 4,
      "start": "Le sauvetage est-il une tâche légale des autorités, et si oui,",
      "end": "à qui incombe-t-elle?"
    },
    {
      "n": 5,
      "start": "Comment la Municipalité voit-elle les importants défis que représentent",
      "end": "les investissements requis ces prochaines années et comment peut-elle aider à les relever?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "La Municipalité relève en préambule et comme mentionné dans l’interpellation",
      "end": "que l’Association du sauvetage d’Ouchy dispose d’une subvention annuelle de CHF 23000.- de la Ville de Lausanne"
    },
    {
      "n": 2,
      "start": "Comme mentionné en préambule, la subvention annuelle de CHF 23000.- de la Ville de Lausanne, versée au travers du Service de protection et sauvetage (SPSL), n’est pas conditionnée pour soutenir des activités précises.",
      "end": "la section en dispose librement pour mener au mieux sa mission."
    },
    {
      "n": 3,
      "start": "Chacune des 34 sections de la SISL est une entité à part entière, jouissant d’une complète autonomie dans la gestion, l’entretien et l’acquisition de locaux, de bateaux ou d’équipements.",
      "end": "Elles se fixent elle-même leur propre budget et trouve chaque année l’argent nécessaire au bon fonctionnement de leurs activités."
    },
    {
      "n": 4,
      "start": "L’article 44, alinéa 2 de la Constitution vaudoise précise que l’Etat et les communes assurent l’ordre public ainsi que la sécurité des personnes et des biens.",
      "end": "La mission du sauvetage fait partie intégrante de la chaîne de secours dont la SISL et ses sections est un des nombreux partenaires."
    },
    {
      "n": 5,
      "start": "La Municipalité pourra exprimer son avis une fois que le nouveau comité élu lors de la dernière assemblée générale de l’association du 16juin 2023 sera en mesure de présenter",
      "end": "une proposition concrète et motivée en lien avec les besoins de sa flotte."
    }
  ],
  "submitter": "Christine Goumaz",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "La Municipalité estime avoir ainsi répondu aux questions de Madame Christine Goumaz.",
    "end": "Ainsi adopté en séance de Municipalité, à Lausanne, le 7 décembre 2023."
  }
}
